'use strict';
const assert=require('node:assert/strict');
const M=require('../analysis/model.js');
const {fixture}=require('./entry_dom_fixture.cjs');
let count=0,failed=0;function test(name,fn){try{fn();count++;console.log('PASS '+name);}catch(e){failed++;console.error('FAIL '+name+'\n'+e.stack);}}
function start(){const f=fixture();f.c2.open('harnessvln',f.app.getContext());return f;}
test('every possible substantive/continuation ordering through 10 slots preserves page and locate boundaries',()=>{for(let length=0;length<=10;length++)for(let mask=0;mask<2**length;mask++){const root={id:M.ROOT,parent:null,label:'root'},focus={id:'f',parent:M.ROOT,label:'focus'},nodes=Array.from({length},(_,i)=>({id:'n'+i,parent:'f',label:mask&(1<<i)?'...':'question'})),m={paperId:'synthetic',nodes:new Map([root,focus,...nodes].map(n=>[n.id,n])),children:new Map([[M.ROOT,[focus]],['f',nodes]])};let s={...M.initial(m),focus:'f'},seen=[];for(let p=0;p<=M.branch(m,s).maxPage;p++){s={...s,pages:{f:p}};const b=M.branch(m,s);assert(b.items.filter(n=>!M.isContinuation(n)).length<=4);for(const n of b.items){assert.equal(M.pageFor(m,'f',n.id),p);const located=M.locate(m,s,n.id);assert(M.branch(m,located).items.some(x=>x.id===n.id));}seen.push(...b.items.map(n=>n.id));}assert.deepEqual(seen,nodes.map(n=>n.id));}});
test('leaf inspect opens correct evidence, traps tab, Escape restores leaf and history restores drawer',()=>{const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');f.click('.c2-node[data-id="method.module1"]');const before=f.historyStack.length;f.click('.c2-node[data-id="method.module1.why"]');assert.equal(f.historyStack.length,before+1,'one leaf activation must add exactly one history state');assert.equal(f.c2.getState().drawer,'evidence');assert.equal(f.c2.getState().selected,'method.module1.why');assert.equal(f.document.activeElement.id,'c2-drawer-back');const controls=f.$('#c2-overlay').querySelectorAll('button, a[href], input, select, textarea, [tabindex="0"]').filter(x=>!x.disabled);controls.at(-1).focus();controls.at(-1).emit('keydown',{key:'Tab'});assert.equal(f.document.activeElement,controls[0]);f.$('#c2-drawer-back').emit('keydown',{key:'Escape'});assert.equal(f.c2.getState().drawer,null);assert.equal(f.document.activeElement.id,'c2-node-method_module1_why');f.back();assert.equal(f.c2.getState().drawer,'evidence');assert.equal(f.c2.getState().selected,'method.module1.why');f.forward();assert.equal(f.c2.getState().drawer,null);});
test('back and root breadcrumb preserve bounded-workspace document scroll and restore attached root focus',()=>{for(const action of ['back','root-crumb']){const f=start();f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="method"]');f.window.scrollY=900;if(action==='back')f.click('[data-c2="back"]');else f.click('.c2-breadcrumb').querySelector('[data-id="'+M.ROOT+'"]').emit('click');assert.equal(f.window.scrollY,900);assert.equal(f.c2.getState().focus,M.ROOT);const selected=f.c2.getState().selected;assert.equal(f.document.activeElement.id,'c2-node-'+selected.replace(/[^\w-]/g,'_'));assert(f.$('#c2-app').querySelectorAll('.c2-node').includes(f.document.activeElement));}});
test('Limitation root leaf, directory and old hash expose evidence and retain visible focus',()=>{for(const entry of ['global','directory','legacy-hash']){const old={paperId:'harnessvln',focus:M.ROOT,selected:'limitation',drawer:null};const f=entry==='legacy-hash'?fixture({url:'https://example.test/local-only/#analysis='+encodeURIComponent(JSON.stringify(old))}):start();if(entry==='legacy-hash'){assert.equal(f.document.activeElement.dataset.id,'limitation');assert.equal(f.document.activeElement.dataset.c2,'inspect');}if(entry==='directory'){f.click('[data-c2="directory"]');const before=f.historyStack.length;f.click('.c2-directory-row[data-id="limitation"]');assert.equal(f.historyStack.length,before+1);}else{const before=f.historyStack.length;f.click('.atlas-vertex[data-atlas-view="analysis"][data-atlas-id="limitation"]');assert.equal(f.c2.getState().selected,'limitation');assert.equal(f.c2.getState().drawer,null);const located=f.historyStack.length;assert(located===before||located===before+1);f.click('[data-c2="evidence"]');assert.equal(f.historyStack.length,located+1);}assert.equal(f.c2.getState().drawer,'evidence');assert.equal(f.c2.getState().selected,'limitation');assert(f.$('#c2-drawer-body').textContent.includes(f.c2.getModel().answers.get('limitation').answer));f.$('#c2-drawer-back').emit('keydown',{key:'Escape'});assert.equal(f.c2.getState().drawer,null);assert.equal(f.document.activeElement.dataset.id,'limitation');assert.equal(f.document.activeElement.dataset.c2,'inspect');assert(f.document.activeElement.classList.contains('c2-node'));f.back();assert.equal(f.c2.getState().drawer,'evidence');f.forward();assert.equal(f.c2.getState().drawer,null);}});
console.log(count+' independent audit checks passed, '+failed+' failed; mocked DOM/geometry only');process.exitCode=failed?1:0;
